def reviewed_authoring_originals(root):
    """Load only the pinned inverse guard, without importing a test module."""
    path = root / "tests/unit/test_arc_profile_native_end_cap.py"
    selected = {}
    for node in ast.parse(path.read_bytes()).body:
        if isinstance(node, ast.Assign) and len(node.targets) == 1:
            target = node.targets[0]
            if isinstance(target, ast.Name) and target.id in {
                "AUTHORING_REVISION_FIXTURE",
                "AUTHORING_REVISION_SHA256",
            }:
                assert isinstance(node.value, ast.Constant)
                assert type(node.value.value) is str
                assert target.id not in selected
                selected[target.id] = node
        elif isinstance(node, ast.FunctionDef) and node.name == "authoring_revision_originals":
            assert node.name not in selected
            selected[node.name] = node
    assert set(selected) == {
        "AUTHORING_REVISION_FIXTURE",
        "AUTHORING_REVISION_SHA256",
        "authoring_revision_originals",
    }
    namespace = {"hashlib": hashlib, "json": json}
    exec(
        compile(ast.Module(body=list(selected.values()), type_ignores=[]), str(path), "exec"),
        namespace,
    )
    return namespace["authoring_revision_originals"](root)

def _authoring_originals(root):
    tree = ast.parse((ROOT / "tests/unit/test_arc_profile_incidence.py").read_bytes())
    outer = next(
        node
        for node in tree.body
        if isinstance(node, ast.FunctionDef) and node.name == INCIDENCE_GUARD
    )
    helper = next(
        node
        for node in outer.body
        if isinstance(node, ast.FunctionDef) and node.name == "reviewed_authoring_originals"
    )
    namespace = {"ast": ast, "hashlib": hashlib, "json": json}
    exec(
        compile(ast.Module(body=[helper], type_ignores=[]), "authoring_boundary", "exec"), namespace
    )
    return namespace[helper.name](root)

